def longest_dictionary_word(s,dictionary):
    best=''
    for word in dictionary:
        index=0
        for char in s:
            if index<len(word) and word[index]==char:index+=1
        if index==len(word) and (len(word)>len(best) or (len(word)==len(best) and word<best)):
            best=word
    return best

